glsl:
vec4 effect(vec2 uv) {
  vec2 cc = uv * 2.0 - 1.0;
  cc *= 1.0 + dot(cc, cc) * 0.09 * uAmount;
  vec2 u = cc * 0.5 + 0.5;
  if (u.x < 0.0 || u.x > 1.0 || u.y < 0.0 || u.y > 1.0) return vec4(0.0, 0.0, 0.0, 1.0);
  vec3 col = getColor(u).rgb;
  float scan = 0.75 + 0.25 * sin(u.y / uTexel.y * 1.6);
  vec3 mask = vec3(1.0 - 0.15 * step(0.5, fract(gl_FragCoord.x / 3.0)), 1.0, 1.0 - 0.15 * step(0.5, fract(gl_FragCoord.x / 3.0 + 0.5)));
  col *= mix(vec3(1.0), scan * mask, uAmount);
  col *= 1.0 - 0.35 * dot(cc, cc) * uAmount;
  col *= 0.97 + 0.03 * sin(uTime * 60.0);
  return vec4(col, getColor(u).a);
}
